const invoiceId = $json.invoice_id || $json.last_invoice_id || null;
const invoiceNumber = $json.invoice_number || null;
if (!invoiceId && !invoiceNumber) throw new Error('invoice identifier is required');
return [{ json: { ...$json, invoice_id: invoiceId, invoice_number: invoiceNumber, status_lookup_requested: true } }];
